\section{Supplementary Tables}

%%% Table S1: Cross-Model Transfer Matrix (Exp-013) %%%
\begin{table}[t]
  \centering
  \caption{Cross-model transfer matrix: 5-class depth classification accuracy (Exp-013).
    Each cell reports the accuracy of an OBD-LightGBM classifier trained on one model's
    features and evaluated on another. Diagonal entries (\textbf{bold}) are within-model
    accuracies. Pythia$\leftrightarrow$OLMo transfers retain 91--92\% of within-model
    accuracy, indicating shared feature geometry across continuation-based models.
    Qwen-rewrite$\to$\{Pythia, OLMo\} shows the largest degradation (61--63\% retention),
    consistent with rewriting introducing model-specific distributional signatures absent
    from continuation-based generation.}
  \label{tab:s1_cross_transfer}
  \begin{tabular}{lcccc}
    \toprule
    \multirow{2}{*}{Train} & \multicolumn{4}{c}{Test} \\
    \cmidrule(lr){2-5}
    & Qwen-rw & Pythia & OLMo & Qwen-cont \\
    \midrule
    Qwen-rw   & \textbf{0.4229} & 0.2590 & 0.2653 & 0.3466 \\
    Pythia    & 0.2718 & \textbf{0.3856} & 0.3531 & 0.3287 \\
    OLMo      & 0.2768 & 0.3450 & \textbf{0.3822} & 0.3244 \\
    Qwen-cont & 0.3440 & 0.3284 & 0.3112 & \textbf{0.3875} \\
    \bottomrule
  \end{tabular}
\end{table}

%%% Table S2: Decoding Strategy Ablation — Complete Pairwise AUC (Exp-003) %%%
\begin{table}[t]
  \centering
  \caption{Complete pairwise $\auc$ for decoding strategy ablation (Exp-003).
    All configurations yield $\auc_{1\text{v}2} > \theta = 0.60$, confirming
    $\Kstar \geq 2$. All $\auc_{2\text{v}3} < 0.60$, placing
    $\Kempirical = 2$ regardless of decoding strategy.
    Nucleus $p{=}0.9$, $T{=}1.0$ produces the 2v3 value closest to the
    threshold (0.5917). Higher temperature ($T{=}1.2$) yields the strongest
    1v2 signal (0.7039).}
  \label{tab:s2_decoding_ablation}
  \begin{tabular}{lccccc}
    \toprule
    Configuration & 0v1 & 1v2 & 2v3 & 3v4 & 4v5 \\
    \midrule
    Greedy                          & 0.9797 & 0.6893 & 0.5613 & 0.5404 & 0.5139 \\
    Nucleus $p{=}0.9$, $T{=}1.0$   & 0.9946 & 0.6866 & 0.5917 & 0.5466 & 0.5068 \\
    Nucleus $p{=}0.95$, $T{=}0.7$  & 0.9878 & 0.6887 & 0.5902 & 0.5393 & 0.5349 \\
    Nucleus $p{=}0.95$, $T{=}1.2$  & 0.9982 & 0.7039 & 0.5823 & 0.5293 & 0.5237 \\
    \bottomrule
  \end{tabular}
\end{table}

%%% Table S3: LLM Zero-Shot Confusion Matrices (Exp-011) %%%
\begin{table}[t]
  \centering
  \caption{LLM zero-shot depth classification: $5 \times 5$ confusion matrices
    and per-depth recall (Exp-011). Both frontier LLMs achieve high binary
    (depth-0 vs.\ $\geq$1) detection accuracy (GPT-5.5: 0.8780; Claude Opus 4.6:
    0.8818) but near-chance 5-class accuracy (${\sim}0.33$ vs.\ OBD-LightGBM
    baseline 0.3856). GPT-5.5 strongly identifies depth-0 (human) text
    (recall 0.7700) but collapses on depth-4 (recall 0.0800), misclassifying
    50/100 depth-4 samples as depth-2. Claude Opus 4.6 shows more uniform
    errors across depths 1--4, with depth-4 recall (0.3700) exceeding
    GPT-5.5 by a wide margin.}
  \label{tab:s3_llm_zeroshot}

  \vspace{0.5em}
  \begin{subtable}{\columnwidth}
    \centering
    \caption{GPT-5.5 ($N{=}500$, accuracy${=}0.3320$, MAE${=}1.1020$, Spearman $\rho{=}0.3834$)}
    \label{tab:s3a_gpt55}
    \begin{tabular}{lcccccc}
      \toprule
      & \multicolumn{5}{c}{Predicted Depth} & \\
      \cmidrule(lr){2-6}
      True Depth & 0 & 1 & 2 & 3 & 4 & Recall \\
      \midrule
      0 (human) & \textbf{77} & 18 &  4 &  0 &  1 & 0.7700 \\
      1         &  9 & \textbf{19} & 36 & 24 & 12 & 0.1900 \\
      2         &  8 & 10 & \textbf{38} & 35 &  9 & 0.3800 \\
      3         & 10 & 16 & 35 & \textbf{24} & 15 & 0.2400 \\
      4         & 11 & 13 & 50 & 18 &  \textbf{8} & 0.0800 \\
      \bottomrule
    \end{tabular}
  \end{subtable}

  \vspace{1em}
  \begin{subtable}{\columnwidth}
    \centering
    \caption{Claude Opus 4.6 ($N{=}499$, accuracy${=}0.3307$, MAE${=}1.1503$, Spearman $\rho{=}0.4162$)}
    \label{tab:s3b_claude}
    \begin{tabular}{lcccccc}
      \toprule
      & \multicolumn{5}{c}{Predicted Depth} & \\
      \cmidrule(lr){2-6}
      True Depth & 0 & 1 & 2 & 3 & 4 & Recall \\
      \midrule
      0 (human) & \textbf{69} & 26 &  3 &  0 &  2 & 0.6900 \\
      1         &  8 & \textbf{21} & 32 & 11 & 28 & 0.2100 \\
      2         &  6 & 36 & \textbf{28} &  5 & 25 & 0.2800 \\
      3         &  7 & 20 & 31 & \textbf{10} & 31 & 0.1010 \\
      4         &  7 & 28 & 22 &  6 & \textbf{37} & 0.3700 \\
      \bottomrule
    \end{tabular}
  \end{subtable}
\end{table}

